public:
    bool increasingTriplet(vector<int>& nums) {
        int n=nums.size();
        int left=INT_MAX,mid=INT_MAX; // we are storing the left boundaries of 1st and the 2nd element.
        for(int i=0;i<n;i++)
        {
            if(nums[i]<=left)
                left=nums[i];
            else if(nums[i]<=mid)
                mid=nums[i];
            else
                return true;
        }
        return false;
    }
};

class Solution(object):
    def increasingTriplet(self, nums):
        """
        :type nums: List[int]
        :rtype: bool
        """
        n = len(nums)
        if n < 3:
            return False
        num1, num2 = nums[0], float("inf")
        for i in range(1, n):
            if nums[i] > num2:
                return True
            elif nums[i] > num1:
                num2 = nums[i]
            else:
                num1 = nums[i]
        return False
